#!/usr/bin/env python3
import json, subprocess, sys

URL = "https://api.linear.app/graphql"
HDRS = ["-H", "Content-Type: application/json", "-H", "Authorization: Bearer <TOKEN>"]

def gql(query, variables=None):
    payload = json.dumps({"query": query, "variables": variables or {}})
    r = subprocess.run(["curl", "-s", URL, *HDRS, "-d", payload], capture_output=True, text=True)
    return json.loads(r.stdout)

# 1) List issues
d = gql("""query { issues(first: 100) { nodes { id identifier title url } } }""")
issues = d["data"]["issues"]["nodes"]
print(f"{len(issues)} issues total", file=sys.stderr)

for issue in issues:
    # 2) Comments + documents per issue
    d2 = gql("""
    query($id: String!) {
      issue(id: $id) {
        identifier
        comments(first: 100) { nodes { body createdAt user { name } } }
        documents(first: 10) { edges { node { title url } } }
      }
    }""", {"id": issue["id"]})
    if "errors" in d2:
        print("ERROR", issue["identifier"], d2["errors"], file=sys.stderr)
        continue
    node = d2["data"]["issue"]
    docs = [e["node"] for e in node.get("documents", {}).get("edges", [])]
    for c in node["comments"]["nodes"]:
        body = c.get("body") or ""
        if "github" in body.lower() or "pull" in body.lower() or "pr " in body.lower() or "#pr" in body.lower():
            print("=== " + node["identifier"] + " | " + issue["title"] + " | " + issue["url"])
            print(f"  comment by {c['user']['name']} @ {c['createdAt']}: {body[:500]}")
    for doc in docs:
        if "github" in doc.get("title", "").lower() or "pull" in doc.get("title", "").lower():
            print("=== " + node["identifier"] + " | doc: " + doc["title"] + " | " + doc["url"])

